import ast,csv,json,math
from pathlib import Path
rows=list(csv.DictReader(open('market.csv', newline='')))
b=json.load(open('memory/baseline_forecasts.json'))
active=[r for r in rows if r['is_resolved'].lower()=='false']
resolved=[r for r in rows if r['is_resolved'].lower()=='true']

def parse(s):
 s=s.strip()
 if not s:return None
 try:return json.loads(s)
 except:return ast.literal_eval(s)
problems=[]
for qid,p in b.items():
 if not isinstance(p,dict):problems.append([qid,'not-dict']);continue
 if len(p)>5:problems.append([qid,'too-many'])
 vals=list(p.values())
 if any(not isinstance(v,(int,float)) or not math.isfinite(v) or v<0 or v>1 for v in vals):problems.append([qid,'bad-prob'])
 if sum(vals)>1.000000001:problems.append([qid,'sum',sum(vals)])
 if any(k in {'Unknown','TBD','Other','N/A'} for k in p):problems.append([qid,'placeholder'])
active_ids={r['qid'] for r in active}
mismatches=sorted(r['qid'] for r in active if parse(r['my_prediction'])"'!=b[r['"'qid']])
expected=sorted(['676856','58896','901922','46784'])
print(json.dumps({
 'market_rows':len(rows),'active':len(active),'resolved':len(resolved),'baseline_entries':len(b),
 'missing_active':sorted(active_ids-set(b)),
 'resolved_baseline_entries':sorted(set(b)-active_ids),
 'validation_problems':problems,
 'day_start_snapshot_mismatches':mismatches,
 'mismatches_match_submissions':mismatches==expected,
 'daily_note_exists':Path('memory/2026-04-04.md').exists()
},indent=2))
PY"

